// Multiple classes in one file for the runnable demo.
package com.bank.backbone;

import java.util.List;
import java.util.logging.*;

public class EventBackboneDemo {

    private static final Logger log = Logger.getLogger(EventBackboneDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Kafka is the single authoritative system of record.
        KafkaSystemOfRecord kafka = new KafkaSystemOfRecord("transactions");
        // The bridge captures everything Solace receives into Kafka.
        SolaceToKafkaBridge bridge = new SolaceToKafkaBridge(kafka);
        // Solace routes live slices to desks AND notifies the bridge.
        SolaceRouter solace = new SolaceRouter(bridge);

        // Desks register changing, diverse routing needs (no topic creation).
        solace.subscribe("mumbai-ops",   "txn/IN/Mumbai/>");
        solace.subscribe("large-monitor", "txn/*/*/large");

        // One publish per event: routed live AND persisted durably.
        List<String[]> events = List.of(
            new String[]{"txn/IN/Mumbai/small",  "SAV2001", "Rajesh Rs.500 debit"},
            new String[]{"txn/IN/Mumbai/large",  "SAV2001", "Rajesh Rs.800000 transfer"},
            new String[]{"txn/BR/SaoPaulo/large", "CUR3001", "Priya Rs.600000 credit"},
            new String[]{"txn/UK/London/small",   "CUR3001", "Priya Rs.300 fee"}
        );
        log.info("=== LIVE routing via Solace + durable capture via Kafka ===");
        for (String[] e : events) solace.publish(e[0], e[1], e[2]);

        // Later: compliance rebuilds the full ledger by replaying Kafka.
        log.info("=== Compliance replay: rebuild ledger from Kafka system of record ===");
        kafka.replayFromStart();
    }
}

