class SolaceRouter {
    private static final Logger log = Logger.getLogger(SolaceRouter.class.getName());
    private final java.util.Map<String, String> subs = new java.util.LinkedHashMap<>();
    private final SolaceToKafkaBridge bridge;
    SolaceRouter(SolaceToKafkaBridge bridge) { this.bridge = bridge; }

    void subscribe(String desk, String pattern) {
        subs.put(desk, pattern);
        log.info(() -> "subscribe " + desk + " -> " + pattern + " (no topic created)");
    }

    void publish(String topic, String key, String payload) {
        // 1) Deliver live slices to matching desks.
        for (var e : subs.entrySet())
            if (matches(e.getValue(), topic))
                log.info(() -> "LIVE -> " + e.getKey() + " : " + topic + " [" + payload + "]");
        // 2) Hand the same event to the bridge for durable capture.
        bridge.onEvent(topic, key, payload);
    }

    boolean matches(String pattern, String topic) {
        String[] p = pattern.split("/"), t = topic.split("/");
        int i = 0;
        for (; i < p.length; i++) {
            if (p[i].equals(">")) return true;
            if (i >= t.length) return false;
            if (p[i].equals("*")) continue;
            if (!p[i].equals(t[i])) return false;
        }
        return i == t.length;
    }
}

// ─── Would be in bridge/SolaceToKafkaBridge.java ───
class SolaceToKafkaBridge {
    private static final Logger log = Logger.getLogger(SolaceToKafkaBridge.class.getName());
    private final KafkaSystemOfRecord kafka;
    SolaceToKafkaBridge(KafkaSystemOfRecord kafka) { this.kafka = kafka; }

    // Every event Solace receives is persisted durably, keyed for ordering.
    void onEvent(String topic, String key, String payload) {
        log.fine(() -> "bridge capture " + topic + " key=" + key);
        kafka.append(key, topic + " | " + payload);     // key preserves per-account order
    }
}

// ─── Would be in kafka/KafkaSystemOfRecord.java ───
class KafkaSystemOfRecord {
    private static final Logger log = Logger.getLogger(KafkaSystemOfRecord.class.getName());
    private final String topic;
    private final java.util.List<String[]> logStore = new java.util.ArrayList<>(); // retained
    KafkaSystemOfRecord(String topic) { this.topic = topic; }

    void append(String key, String value) {
        logStore.add(new String[]{key, value});
        log.info(() -> "KAFKA append " + topic + " key=" + key + " offset=" + (logStore.size()-1));
    }

    void replayFromStart() {                             // deterministic replay for event sourcing
        for (int i = 0; i < logStore.size(); i++) {
            String[] rec = logStore.get(i);
            int off = i;
            log.info(() -> "REPLAY offset=" + off + " key=" + rec[0] + " -> " + rec[1]);
        }
    }
}

